  "decline_reason": "",
  "claims": [
    {
      "text": "For an FOI request, the Manual says third-party consultation is required if a document contains business information or personal information relating to a third party.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/3",
          "quote": "2.3.3 If a document contains business information or personal information relating to a third party, under the FOI Act, third party consultation is required"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For documents containing sensitive business or personal information, the Manual says the trade mark applicant or their representative may be contacted and given an opportunity to argue that some or all of the information is exempt from release; this particular passage uses “may”, rather than guaranteeing contact in every case.",
      "quotes": [
        {
          "ref": "TMM/Part61/3/3/3",
          "quote": "To the extent that these documents contain sensitive business and/or personal information, the trade mark applicant or their representative may be contacted and given the opportunity to contend that all or part of the information is exempt from release."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Where the affected party argues that information is exempt, the Manual says they have the right to request internal review and/or OAIC review before the documents are released to the FOI applicant.",
      "quotes": [
        {
          "ref": "TMM/Part61/3/3/3",
          "quote": "Where the affected party contends information is exempt, they will have the right to request an internal review and/or a review conducted by the Office of the Australian Information Commissioner (OAIC) – before documents are released to the FOI applicant."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Simply claiming confidentiality is not enough to secure confidential treatment: the Manual separately states that the Registrar will not accept or acknowledge an applicant’s claim that information in particular documents is confidential.",
      "quotes": [
        {
          "ref": "TMM/Part61/3/3/4",
          "quote": "A claim from the applicant that the information in particular documents is confidential will not be accepted or acknowledged by the Registrar."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Public inspection under section 217A is a separate access route: the Act requires the Registrar to make prescribed trade mark documents available for public inspection while held in the Trade Marks Office at or after publication of the application particulars under section 30.",
      "quotes": [
        {
          "ref": "TMA1995/s217A",
          "quote": "(1) The Registrar must make available for public inspection prescribed documents that relate to a trade mark while they are held in the Trade Marks Office at or after the time particulars of the application for registration of the trade mark are published under section 30."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The supplied passages therefore support an opportunity to object and seek review in the stated FOI circumstances, but do not establish a universal right to consultation before every form of document access; they do not provide enough information to determine whether particular documents would be released.",
      "quotes": [],
      "authority": "none"
    }
  ],
  "declined": false,
